package com.bicheon.advisor.dev356;
import android.app.*;import android.content.*;import android.media.projection.*;import android.os.*;import android.content.pm.ServiceInfo;
public class AdvisorService extends Service{MediaProjection p;AdvisorEngine e;static final String CH="bicheon";public void onCreate(){super.onCreate();try{if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel(CH,"비천 매치 추천기",NotificationManager.IMPORTANCE_LOW));}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CH):new Notification.Builder(this);Notification no=b.setContentTitle("비천 매치 추천기").setContentText("화면 분석 중").setSmallIcon(android.R.drawable.ic_menu_view).build();if(Build.VERSION.SDK_INT>=29)startForeground(3561,no,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(3561,no);}catch(Throwable x){stopSelf();}}public int onStartCommand(Intent i,int f,int id){try{if(i==null){stopSelf();return START_NOT_STICKY;}int rc=i.getIntExtra("rc",0);Intent d=i.getParcelableExtra("data");MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);p=m.getMediaProjection(rc,d);if(p==null){stopSelf();return START_NOT_STICKY;}e=new AdvisorEngine(this,p);e.start();return START_NOT_STICKY;}catch(Throwable x){stopSelf();return START_NOT_STICKY;}}public void onDestroy(){try{if(e!=null)e.stop();}catch(Throwable x){}try{if(p!=null)p.stop();}catch(Throwable x){}super.onDestroy();}public IBinder onBind(Intent i){return null;}}
